library(creditratingsystem)
cases<-jsonlite::fromJSON('[{"X": [[0, 0], [1, 10], [2, 20], [3, 30]], "model_contract": {"model_id": "ale", "model_version": "1", "feature_order": ["x", "y"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}, "selected_features": ["x"], "bins": {"x": [0, 1, 2, 3]}, "feature_types": {"x": "continuous"}, "weights": [1, 1, 2, 2]}, {"X": [[-1, -1], [-1, 1], [1, -1], [1, 1]], "model_contract": {"model_id": "ale", "model_version": "1", "feature_order": ["x", "y"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}, "selected_features": ["x", "y"], "bins": {"x": [-1, 0, 1], "y": [-1, 0, 1]}, "feature_types": {"x": "continuous", "y": "continuous"}}, {"X": [[-1, -1], [-1, 1], [1, -1], [1, 1]], "model_contract": {"model_id": "ale", "model_version": "1", "feature_order": ["x", "y"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}, "selected_features": ["x", "y"], "bins": {"x": [-1, 0, 1], "y": [-1, 0, 1]}, "feature_types": {"x": "continuous", "y": "continuous"}}, {"X": [[-1, -1], [1, 1]], "model_contract": {"model_id": "ale", "model_version": "1", "feature_order": ["x", "y"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}, "selected_features": ["x", "y"], "bins": {"x": [-1, 0, 1], "y": [-1, 0, 1]}, "feature_types": {"x": "continuous", "y": "continuous"}}, {"X": [[0, 0], [1, 1]], "model_contract": {"model_id": "ale", "model_version": "1", "feature_order": ["x", "y"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}, "selected_features": ["x"], "bins": {"x": [0, 1]}, "feature_types": {"x": "continuous"}, "weights": [1, 0], "min_bin_count": 2}]',simplifyVector=FALSE);out<-list()
for(i in seq_along(cases)){
 a<-cases[[i]];if(!is.null(a$weights))a$weights<-unlist(a$weights);a$predictor<-switch(i,function(z)2*z[,1]+3*z[,2],function(z)z[,1]*z[,2],function(z)2*z[,1]+3*z[,2],function(z)z[,1]*z[,2],function(z)z[,1])
 r<-do.call(compute_credit_ale,a);out[[i]]<-list(value=r$value,diagnostics=r$diagnostics)
}
stopifnot(max(abs(unlist(out[[1]]$value$centered_ale_grid)-c(-11/3,-5/3,1/3,7/3)))<1e-14,all(unlist(out[[2]]$value$centered_ale_grid)==c(1,0,-1,0,0,0,-1,0,1)),all(unlist(out[[3]]$value$centered_ale_grid)==0),out[[4]]$value$status=='NON_ESTIMABLE_SUPPORT',is.null(out[[4]]$value$centered_ale_grid),out[[5]]$value$positive_weight_counts[[1]]==1,is.null(out[[5]]$value$centered_ale_grid))
